          "sample": "Die Behauptung ist falsch. Lina schreibt hier einer einzelnen Person und wählt „vous“ als höfliche Anrede. „Vous“ kann in einem anderen Zusammenhang auch mehrere Personen ansprechen.",
          "writingLines": 4,
