            "Z6 oder Z8 wird als passender Wahrnehmungs- oder Wissenshinweis erläutert.",
            "Bens Gedanken, sein Motiv beim Schweigen oder sein Wissen über den Vorfall werden ausdrücklich als unbekannt benannt."
