      "scope": "Freiwillige, gestützte Sprachmittlung im 7/8-Rahmen. § 2.2.5 beschreibt ein Ziel bis Ende Klasse 8; die Übung ist kein Nachweis des aktuellen Klasse-7-Unterrichts.",
      "levelStatus": "grade78-flex",
