      "scope": "Freiwilliger, gestützter Klasse-7-Einstieg in die exemplarische 7/8-Textsorte Rollenbiografie; Schreibziel bis Ende Klasse 8. Keine bestätigte aktuelle Schuleinheit.",
      "levelStatus": "grade78-flex",
